@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1>Project Board</h1>

@if (isLoading)
{
    <p><em>Loading tasks...</em></p>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger">@errorMessage</div>
}
else
{
    <!-- Stats Bar -->
    <div class="stats-bar d-flex gap-3 mb-3 p-3 bg-light rounded">
        <span><strong>Total:</strong> @filteredTasks.Count</span>
        <span><strong>To Do:</strong> @GetColumnTasks("To Do").Count</span>
        <span><strong>In Progress:</strong> @GetColumnTasks("In Progress").Count</span>
        <span><strong>Done:</strong> @GetColumnTasks("Done").Count</span>
        <span class="text-danger"><strong>Overdue:</strong> @filteredTasks.Count(t => t.DueDate < DateTime.Today)</span>
    </div>

    <!-- Search Bar -->
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Search tasks by title..."
               @bind="searchText" @bind:event="oninput" />
    </div>

    <!-- Kanban Columns -->
    <div class="d-flex gap-3">
        @foreach (var column in columns)
        {
            var columnTasks = GetColumnTasks(column);
            var colIndex = Array.IndexOf(columns, column);

            <div class="card flex-fill">
                <div class="card-header">
                    <strong>@column</strong> <span class="badge bg-secondary">@columnTasks.Count</span>
                </div>
                <div class="card-body">
                    @foreach (var task in columnTasks)
                    {
                        <div class="card mb-2">
                            <div class="card-body p-2">
                                <h6 class="card-title mb-1">@task.Title</h6>
                                <p class="card-text mb-1">
                                    <small>@task.Assignee</small>
                                </p>
                                <span class="badge @GetPriorityClass(task.Priority)">@task.Priority</span>
                                <small class="ms-2">@task.DueDate.ToString("MMM dd")</small>
                                <div class="mt-2">
                                    @if (colIndex > 0)
                                    {
                                        <button class="btn btn-sm btn-outline-secondary me-1"
                                                @onclick="() => MoveTask(task.Id, columns[colIndex - 1])">
                                            &larr; Move Left
                                        </button>
                                    }
                                    @if (colIndex < columns.Length - 1)
                                    {
                                        <button class="btn btn-sm btn-outline-secondary"
                                                @onclick="() => MoveTask(task.Id, columns[colIndex + 1])">
                                            Move Right &rarr;
                                        </button>
                                    }
                                </div>
                            </div>
                        </div>
                    }

                    @if (showFormForColumn == column)
                    {
                        <div class="card mb-2 border-primary">
                            <div class="card-body p-2">
                                <input type="text" class="form-control form-control-sm mb-1"
                                       placeholder="Title" @bind="newTitle" />
                                <input type="text" class="form-control form-control-sm mb-1"
                                       placeholder="Assignee" @bind="newAssignee" />
                                <select class="form-select form-select-sm mb-1" @bind="newPriority">
                                    <option value="High">High</option>
                                    <option value="Medium">Medium</option>
                                    <option value="Low">Low</option>
                                </select>
                                <input type="date" class="form-control form-control-sm mb-1"
                                       @bind="newDueDate" />
                                <div class="d-flex gap-1">
                                    <button class="btn btn-sm btn-primary"
                                            @onclick="() => SaveTask(column)">Save</button>
                                    <button class="btn btn-sm btn-secondary"
                                            @onclick="CancelAdd">Cancel</button>
                                </div>
                            </div>
                        </div>
                    }
                    else
                    {
                        <button class="btn btn-sm btn-outline-primary w-100"
                                @onclick="() => ShowAddForm(column)">+ Add Task</button>
                    }
                </div>
            </div>
        }
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private bool isLoading = true;
    private string? errorMessage;
    private string searchText = string.Empty;

    private string? showFormForColumn;
    private string newTitle = string.Empty;
    private string newAssignee = string.Empty;
    private string newPriority = "Medium";
    private DateTime newDueDate = DateTime.Today.AddDays(7);

    private static readonly string[] columns = { "To Do", "In Progress", "Done" };

    private List<TaskItem> filteredTasks =>
        string.IsNullOrWhiteSpace(searchText)
            ? allTasks
            : allTasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> GetColumnTasks(string status) =>
        filteredTasks.Where(t => t.Status == status).ToList();

    private string GetPriorityClass(string priority) => priority switch
    {
        "High" => "bg-danger",
        "Medium" => "bg-warning text-dark",
        "Low" => "bg-success",
        _ => "bg-secondary"
    };

    private async Task MoveTask(int taskId, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var index = allTasks.FindIndex(t => t.Id == taskId);
            if (index >= 0)
            {
                var old = allTasks[index];
                allTasks[index] = old with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private void ShowAddForm(string column)
    {
        showFormForColumn = column;
        newTitle = string.Empty;
        newAssignee = string.Empty;
        newPriority = "Medium";
        newDueDate = DateTime.Today.AddDays(7);
    }

    private void CancelAdd()
    {
        showFormForColumn = null;
    }

    private async Task SaveTask(string column)
    {
        if (string.IsNullOrWhiteSpace(newTitle))
            return;

        try
        {
            var created = await TaskService.CreateTaskAsync(newTitle, newAssignee, newPriority, newDueDate);
            // The service creates with a default status; update to match the target column if needed
            if (created.Status != column)
            {
                await TaskService.UpdateTaskStatusAsync(created.Id, column);
                created = created with { Status = column };
            }
            allTasks.Add(created);
            showFormForColumn = null;
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}

